/* Meesho Merchant concept. Every business, price, quote and transaction below is demo data. */
const STORE='meesho-merchant-demo-v1';
const iconPaths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 7V6a4 4 0 0 1 8 0v1"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',request:'<path d="M14 3H5v18h14V8Z"/><path d="M14 3v5h5M8 12h8M8 16h6"/>',orders:'<path d="m3 7 9-4 9 4v10l-9 4-9-4Z"/><path d="m3 7 9 4 9-4M12 11v10M7 5l10 4"/>',truck:'<path d="M2 6h12v12H2ZM14 10h4l4 5v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',swap:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M3 7V5h16v16H3V7Zm0 0h16M15 12h6v5h-6Z"/>',message:'<path d="M21 3H3v14h5l4 4 4-4h5Z"/><path d="M7 8h10M7 12h6"/>',leaf:'<path d="M20 3c0 10-2 17-10 17a7 7 0 0 1-7-7C3 5 10 3 20 3ZM5 18 16 7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',edit:'<path d="m16 3 5 5L9 20l-6 1 1-6ZM13 6l5 5"/>'};
const ico=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.bag}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n)=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:0});
const button=(label,action,args='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${args}>${label}</button>`;
const pic=(id,cls='')=>{const photoId=product(id)?.photoId??(id%24);return `<div class="photo ${cls}" role="img" aria-label="${esc(product(id)?.name||'Home textile product')}" style="--x:${(photoId%6)*20}%;--y:${Math.floor(photoId/6)*100/3}%"></div>`;};
const seedProducts=()=>[
 ['Sage cotton bath towel','Towels',90,50,800,'70 × 140 cm · 500 GSM','Sage green'],['Blush cotton bath towel','Towels',94,50,650,'70 × 140 cm · 500 GSM','Blush pink'],['Hotel white bath towel','Towels',88,100,1200,'70 × 140 cm · 450 GSM','Ivory'],['Navy cotton hand towel','Towels',38,50,900,'40 × 60 cm · 400 GSM','Navy'],['Lilac everyday face towel','Towels',22,100,1500,'30 × 30 cm · 350 GSM','Lilac'],['Mustard kitchen towel','Kitchen linen',32,50,700,'40 × 60 cm · cotton','Mustard'],
 ['Terracotta stripe bedsheet','Bedsheets',310,20,260,'Double · 220 × 240 cm','Terracotta'],['Indigo floral bedsheet','Bedsheets',340,20,190,'Double · cotton · 2 pillow covers','Indigo'],['Sage botanical bedsheet','Bedsheets',365,20,300,'King · 240 × 260 cm','Sage'],['Peach paisley bedsheet','Bedsheets',295,20,220,'Double · 144 thread count','Peach'],['Ivory waffle blanket','Throws & blankets',420,15,140,'150 × 200 cm · cotton','Ivory'],['Burgundy fringed throw','Throws & blankets',280,20,180,'130 × 170 cm · woven','Burgundy'],
 ['Botanical linen cushion cover','Cushion covers',68,50,850,'40 × 40 cm · cover only','Natural'],['Terracotta velvet cushion cover','Cushion covers',75,50,600,'40 × 40 cm · zip closure','Terracotta'],['Geometric cotton cushion cover','Cushion covers',62,50,1100,'40 × 40 cm · cover only','Black / ivory'],['Mustard tufted cushion cover','Cushion covers',96,30,380,'45 × 45 cm · cover only','Mustard'],['Indigo block-print cushion cover','Cushion covers',82,50,450,'40 × 40 cm · cotton','Indigo'],['Blush plain cushion cover','Cushion covers',55,50,980,'40 × 40 cm · cover only','Blush'],
 ['Natural linen table runner','Table linen',140,25,320,'35 × 180 cm · linen blend','Natural'],['Moss cotton placemat set','Table linen',120,30,400,'Set of 4 · 35 cm round','Moss'],['White dinner napkin set','Table linen',105,30,550,'Set of 4 · 40 × 40 cm','White'],['Stripe cotton kitchen apron','Kitchen linen',85,30,270,'Adult · adjustable straps','Terracotta'],['Textured cotton bath mat','Towels',115,30,360,'50 × 80 cm · cotton','Beige'],['Quilted oven mitt set','Kitchen linen',98,30,290,'Mitt + pot holder · cotton','Sage']
].map((p,id)=>({id,name:p[0],category:p[1],price:p[2],moq:p[3],stock:p[4],spec:p[5],colour:p[6],supplier:id%3===0?'Panipat Loomworks':id%3===1?'Northline Textile Traders':'Karnal Home Wholesale',type:id%3===0?'Manufacturer':id%3===1?'Trading supplier':'Wholesaler',active:true}));
function seed(){return {version:1,products:seedProducts(),cart:[],saved:[],plan:'peruse',planUsed:0,service:'managed',feedSaved:[],feedPassed:[],toured:[],requests:[{id:'REQ-101',name:'Sage bath towels for my shop',productId:0,category:'Towels',qty:200,spec:'100% cotton, 500 GSM, 70 × 140 cm, sage green. New unused stock; consistent colour and weight.',kind:'Ready stock',date:'2026-10-18',budget:100,payment:'Advance is workable',baseline:20800,status:'Quotes ready',sampleApproved:false,messages:[{by:'Merchant',text:'Three illustrative routes are ready. Compare quantity, payment timing and the complete basket—not just unit price.'}],quotes:[{id:'Q-101',supplier:'Panipat Loomworks',type:'Manufacturer',price:90,moq:200,freight:600,sample:150,setup:0,loss:200,days:0,lead:5,stock:800,note:'New unused ready stock. Sample matches the specified 500 GSM towel.',requiresSample:true,confirmed:true},{id:'Q-102',supplier:'Karnal Home Wholesale',type:'Wholesaler',price:96,moq:50,freight:300,sample:0,setup:0,loss:100,days:30,lead:2,stock:450,note:'Mixed small lots available. Existing 30-day credit relationship assumed for this demo.',requiresSample:false,confirmed:true},{id:'Q-103',supplier:'Northline Textile Traders',type:'Trading supplier',price:94,moq:100,freight:650,sample:150,setup:0,loss:200,days:0,lead:6,stock:600,note:'Full specified quantity. Advance payment; sample required.',requiresSample:true,confirmed:true}]},{id:'REQ-102',name:'Botanical cushion covers with a simple print',productId:12,category:'Cushion covers',qty:100,spec:'Cotton-linen blend, 40 × 40 cm, hidden zip. One botanical screen print, natural base. Covers only. Sample approval required.',kind:'Bounded customisation',date:'2026-10-28',budget:95,payment:'Advance is workable',baseline:11500,status:'Awaiting quotes',sampleApproved:false,messages:[],quotes:[]}],orders:[]};}
let state;try{const stored=JSON.parse(localStorage.getItem(STORE));state=stored?.version===1&&Array.isArray(stored.products)&&Array.isArray(stored.requests)?stored:seed();}catch{state=seed();}
let role=null,view='home',filter='All products',query='',sort='recommended',onlySaved=false,selectedRequest='REQ-101',tourStep=-1,modalFocus=null;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Your browser could not save this session. The demo still works until you close it.');}}
function product(id){return state.products.find(p=>p.id===Number(id));}
function request(id=selectedRequest){return state.requests.find(r=>r.id===id);}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
function navigate(next){view=next;closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
const categories=['All products','Towels','Bedsheets','Cushion covers','Table linen','Kitchen linen','Throws & blankets'];
function header(){return `<header class="topbar"><button class="text-link" data-action="landing" aria-label="Meesho Merchant home"><div class="brand"><strong>meesho</strong><span>merchant</span></div><span class="brand-demo">Concept demo · sample data</span></button><div class="top-actions"><span class="badge">Concept demo · sample data</span>${role?button(ico('spark')+'<span class="desktop-only">Walkthrough</span><span class="mobile-only">Guide</span>','tour','aria-label="Replay walkthrough"','secondary small')+button(ico('swap')+`<span class="desktop-only">Switch to </span><span class="switch-role">${role==='buyer'?'seller':'buyer'}</span>`,'switch',`aria-label="Switch to ${role==='buyer'?'seller':'buyer'}"`,'quiet small'):button('How it works','about','','secondary small')}${button(ico('help'),'demohelp','aria-label="Demo controls"','quiet small')}</div></header>`;}
function navItems(){return role==='buyer'?[['home','home','Discover'],['requests','request','My requests'],['cart','bag','My basket'],['orders','orders','Orders'],['plans','wallet','Buying help']]:[['home','home','Overview'],['feed','request','Buyer requests'],['inventory','grid','My stock'],['orders','orders','Orders'],['quotes','message','My price offers']];}
function sidebar(){return `<aside class="sidebar"><div class="identity"><div class="avatar">${role==='buyer'?'SH':'PL'}</div><div><strong>${role==='buyer'?'Sharma Home Store':'Demo supplier network'}</strong><small>${role==='buyer'?'Buyer · Karnal':'Seller side · Panipat / Karnal'}</small></div></div><nav class="navlist" aria-label="Main navigation">${navItems().map(([id,icon,label])=>`<button class="navitem ${view===id?'active':''}" data-action="nav" data-view="${id}">${ico(icon)}${label}${id==='cart'&&state.cart.length?`<span class="count">${state.cart.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>From your list to checked stock.</strong><p>${role==='buyer'?'Find products, compare the total cost and follow delivery. Choose buying help when you need it.':'See what shops need. Send your price and terms. Pay zero sales commission.'}</p>${button('Show me around '+ico('arrow'),'tour','','secondary small full')}</div><small class="muted">Panipat → Karnal pilot concept<br>All activity is simulated.</small></aside>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="Mobile navigation">${navItems().map(([id,icon,label])=>`<button class="${view===id?'active':''}" data-action="nav" data-view="${id}">${ico(icon)}<span>${label}</span></button>`).join('')}</nav>`;}
function landing(){return `<main class="landing" id="main"><div class="welcome"><div><h1>Better buying.<br><em>For independent<br>shops.</em></h1><p>Get the right products, in quantities your shop can use, at a clear total cost. Merchant helps organise the purchase, follow delivery and check what arrives.</p><div class="inline-note">${ico('check')}No passwords. No real payments. Explore both sides.</div><div class="entry-grid"><button class="entry" data-action="enter" data-role="buyer">${ico('bag')}<h3>I run a shop</h3><p>Find products, compare supplier prices and try a buying job from order to delivery.</p><span class="enter">Enter as buyer ${ico('arrow')}</span></button><button class="entry" data-action="enter" data-role="seller">${ico('orders')}<h3>I supply products</h3><p>List products, respond to shop requests and follow orders through delivery.</p><span class="enter">Enter as seller ${ico('arrow')}</span></button></div><small class="muted">An interactive Meesho Merchant proposal. Not a live Meesho service.</small></div><div class="welcome-art" aria-label="Home textiles available in the demo">${pic(0)}${pic(6)}${pic(12)}${pic(18)}</div></div><section class="landing-explain"><div>${ico('grid')}<h3>The right products and quantity</h3><p>Start with products already in stock. Need a simple change? Describe the material, size, colour and quantity.</p></div><div>${ico('wallet')}<h3>Know the total cost</h3><p>See product price, delivery, samples, payment timing and the buying help fee separately.</p></div><div>${ico('leaf')}<h3>One complete buying job</h3><p>Merchant helps confirm your list, compare costs, agree terms, track delivery and check receipt. Browsing is free.</p></div></section><div class="demo-footer">Demo suppliers, product images, prices and histories are illustrative. Nothing is purchased, shipped or verified here.</div></main>`;}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function productCard(p){return `<article class="product"><button class="image-button" data-action="product" data-id="${p.id}" aria-label="View ${esc(p.name)}">${pic(p.id)}</button><span class="ribbon badge ${p.id%3===0?'green':'pink'}">${p.id%3===0?'Ready stock':'Small lots'}</span><button class="save ${state.saved.includes(p.id)?'on':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${state.saved.includes(p.id)}">${ico('heart')}</button><div class="product-body"><p>${esc(p.type)} · ${esc(p.supplier)}</p><h3>${esc(p.name)}</h3><div class="spec-line">${esc(p.spec)}</div><div class="price">${money(p.price)} <small>each at min. / ${p.id===19||p.id===20||p.id===23?'set':'unit'}</small></div><div class="product-bottom"><small class="muted">Minimum ${p.moq} units · ${p.stock} in stock</small>${button('Add '+ico('plus'),'add',`data-id="${p.id}"`,'secondary small')}</div></div></article>`;}
function catalogue(home){let list=state.products.filter(p=>p.active&&(filter==='All products'||p.category===filter)&&(!onlySaved||state.saved.includes(p.id))&&`${p.name} ${p.category} ${p.spec} ${p.supplier} ${p.colour}`.toLowerCase().includes(query.toLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='min')list.sort((a,b)=>a.moq-b.moq);return `${home?`<section class="hero"><div class="hero-copy"><h1>Better buying.<br>For independent shops.</h1><p>Find the right home textiles, choose a quantity your shop can use and see the total cost before ordering.</p>${button('Compare supplier prices '+ico('arrow'),'compare',`data-id="REQ-101"`)}</div><div class="hero-image">${pic(6)}<div class="floating">${ico('check')}Ready-stock home textiles</div></div></section><div class="stepsbar"><span>${ico('grid')}Find the right products</span><span>${ico('request')}Compare total cost</span><span>${ico('truck')}Follow the buying job</span></div>`:''}<div class="section-title"><h2>Find products for your shop</h2>${button('Tell us what you need '+ico('plus'),'nav','data-view="newrequest"','secondary small')}</div><div class="toolbar"><label class="search">${ico('search')}<input id="search" aria-label="Search home textiles" placeholder="Search towels, cushion covers, suppliers…" value="${esc(query)}"></label><select id="sort" aria-label="Sort products"><option value="recommended" ${sort==='recommended'?'selected':''}>Recommended</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="min" ${sort==='min'?'selected':''}>Lowest minimum quantity</option></select></div><div class="filters" aria-label="Product categories">${categories.map(c=>`<button class="pillbutton ${filter===c&&!onlySaved?'active':''}" data-action="filter" data-category="${c}">${c}</button>`).join('')}<button class="pillbutton ${onlySaved?'active':''}" data-action="saved">${ico('heart')} Saved</button></div><p class="muted" style="font-size:12px;margin-bottom:15px">${list.length} products · Example prices at the minimum quantity · Open a product to see prices for larger quantities</p><div class="products" id="catalogue">${list.length?list.map(productCard).join(''):`<div class="empty wide">${ico('search')}<h3>No matching stock</h3><p>Try another search, or tell us the product, size, colour and quantity you need.</p>${button('Clear filters','clearfilters','','secondary')}</div>`}</div>`;}

const unitMoney=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
function priceTiers(p){return [1,2,4,8].map((multiple,i)=>({qty:p.moq*multiple,discount:(p.discounts||[0,3,6,8])[i],price:Math.round(p.price*(1-(p.discounts||[0,3,6,8])[i]/100)*100)/100})).filter(t=>t.qty<=p.stock);}
function quantityPrice(p,qty){return priceTiers(p).filter(t=>t.qty<=qty).at(-1)?.price??p.price;}
function quantityWidget(p,qty,context){const tiers=priceTiers(p),next=tiers.find(t=>t.qty>qty),rate=quantityPrice(p,qty);return `<div class="quantity-pricing" data-product="${p.id}" data-context="${context}"><div class="quantity-controls"><div class="quantity-heading"><label for="quantity-${context}-${p.id}">Choose quantity</label><output class="quantity-value" for="quantity-${context}-${p.id}">${qty} units</output></div><input class="quantity-slider" id="quantity-${context}-${p.id}" aria-label="${esc(p.name)} quantity" type="range" min="${p.moq}" max="${p.stock}" step="1" value="${qty}" data-context="${context}" data-id="${p.id}"><div class="range-limits"><span>Minimum ${p.moq}</span><span>Stock ${p.stock}</span></div><div class="price-breaks" aria-label="Prices for larger quantities">${tiers.map(t=>`<button class="price-break ${t.qty===tiers.filter(t=>t.qty<=qty).at(-1)?.qty?'selected':''}" data-action="tierqty" data-id="${p.id}" data-context="${context}" data-qty="${t.qty}"><span>${t.qty}+ units</span><strong>${unitMoney(t.price)}</strong><small>${t.discount?t.discount+'% lower':'Base price'}</small></button>`).join('')}</div><div class="quantity-costs" aria-live="polite"><span>Selected unit price<strong class="selected-unit">${unitMoney(rate)}</strong></span><span>Products total<strong class="selected-goods">${money(rate*qty)}</strong></span></div></div><p class="quantity-next">${next?`Next lower unit price at ${next.qty} units (${next.qty-qty} more).`:'Lowest listed unit price for this stock.'}</p><p class="definition">Example prices: the selected price applies to every unit. A lower unit price can still mean spending more in total. Buy a quantity you can use; delivery and buying help cost extra.</p></div>`;}
function setQuantity(widget,value){const p=product(widget.dataset.product),qty=Math.min(p.stock,Math.max(p.moq,Math.round(Number(value)||p.moq))),tiers=priceTiers(p),tier=tiers.filter(t=>t.qty<=qty).at(-1),next=tiers.find(t=>t.qty>qty),rate=quantityPrice(p,qty);widget.querySelector('input').value=qty;widget.querySelector('output').textContent=qty+' units';widget.querySelector('.selected-unit').textContent=unitMoney(rate);widget.querySelector('.selected-goods').textContent=money(rate*qty);widget.querySelector('.quantity-next').textContent=next?`Next lower unit price at ${next.qty} units (${next.qty-qty} more).`:'Lowest listed unit price for this stock.';widget.querySelectorAll('.price-break').forEach(b=>b.classList.toggle('selected',Number(b.dataset.qty)===tier?.qty));if(widget.dataset.context==='cart'){state.cart.find(c=>c.id===p.id).qty=qty;persist();const t=cartTotals();document.querySelector(`[data-line-total="${p.id}"]`).textContent=money(rate*qty);for(const k of ['goods','freight','fee','total'])document.querySelector(`[data-basket-total="${k}"]`).textContent=money(t[k]);}else{document.querySelector('[data-action="addselected"]').dataset.qty=qty;document.querySelector('[data-action="addselected"]').textContent=`Add ${qty} units to basket`;}positionTour();}

function cartTotals(){const goods=state.cart.reduce((a,c)=>a+quantityPrice(product(c.id),c.qty)*c.qty,0),freight=state.cart.length?Math.max(300,Math.round(goods*.025)):0;const fee=serviceFee();return {goods,freight,fee,total:goods+freight+fee};}
function serviceFee(){return state.service==='self'?0:state.plan==='monthly'&&state.planUsed<4?0:349;}
function serviceChoices(){return `<h3>Who will handle this buying job?</h3><label class="choice"><input type="radio" name="service" value="managed" ${state.service==='managed'?'checked':''}><div><strong>Merchant handles the buying work</strong><p>Confirm your list, compare costs, agree terms, track delivery and check receipt.</p></div><span class="amount">${serviceFee()===0&&state.plan==='monthly'?'<small>Included in plan</small>':'₹349'}</span></label><label class="choice"><input type="radio" name="service" value="self" ${state.service==='self'?'checked':''}><div><strong>I’ll handle it myself</strong><p>Browse for free and arrange the purchase directly. No monthly plan needed.</p></div><span class="amount">₹0</span></label>`;}
function cartView(){const t=cartTotals();return pageHead('Your buying basket','Choose a quantity your shop can use. Check product cost, delivery and the buying help fee before ordering.')+(state.cart.length?`<div class="split"><section class="panel"><h2>${state.cart.length} selected products</h2>${state.cart.map(c=>{const p=product(c.id);return `<div class="basket-line"><div class="item-row">${pic(p.id,'thumb')}<div><h3>${esc(p.name)}</h3><p>${esc(p.spec)} · ${esc(p.supplier)}</p>${button('Remove','remove',`data-id="${p.id}"`,'quiet small')}</div><div class="money" data-line-total="${p.id}">${money(quantityPrice(p,c.qty)*c.qty)}</div></div>${quantityWidget(p,c.qty,'cart')}</div>`;}).join('')}<div class="notice" style="margin-top:20px">These example products are new and unused. Each supplier issues its own product invoice. The service does not buy back stock your shop cannot sell.</div></section><section class="panel basket-summary" id="tour-target"><div class="service-choices">${serviceChoices()}</div><div class="receipt"><div><span>Products · paid to suppliers</span><strong data-basket-total="goods">${money(t.goods)}</strong></div><div><span>Delivery · estimated charge</span><strong data-basket-total="freight">${money(t.freight)}</strong></div><div><span>Merchant buying help fee</span><strong data-basket-total="fee">${money(t.fee)}</strong></div><div class="total"><span>Demo payable</span><span data-basket-total="total">${money(t.total)}</span></div></div><p class="definition">Example amounts include the demo’s tax assumptions. Delivery is an estimate. This demo never asks for card or bank details.</p>${button('Review demo order '+ico('arrow'),'checkoutcart','','full')}<button class="text-link" data-action="nav" data-view="plans">When does a monthly plan make sense?</button></section></div>`:empty('Your basket is ready for a first purchase','Choose a product and add its minimum quantity. Change the quantity before placing a demo order.','Browse home textiles','home'));}
function empty(title,desc,label,next){return `<div class="panel empty">${ico('bag')}<h2>${title}</h2><p>${desc}</p>${button(label,'nav',`data-view="${next}"`)}</div>`;}
function requestsView(){return pageHead('What your shop needs','Share your product list, quantity, date and payment needs. Suppliers reply with prices and terms.',button('New request '+ico('plus'),'nav','data-view="newrequest"'))+`<section class="panel" id="tour-target">${state.requests.map(r=>`<article class="request-row">${pic(r.productId,'thumb')}<div class="info"><div class="row"><span class="request-kind">${esc(kindLabel(r.kind))}</span><span class="badge ${r.quotes.length?'green':'amber'}">${esc(r.status)}</span></div><h3>${esc(r.name)}</h3><p>${r.qty} units · Karnal · Needed by ${formatDate(r.date)}</p><small class="muted">${r.id} · ${r.quotes.length} quotes · ${r.sampleApproved?'Sample approved':'Sample approval where required'}</small></div>${button(r.quotes.length?'Compare quotes':'View request','compare',`data-id="${r.id}"`,'secondary small')}</article>`).join('')}</section>`;}
function kindLabel(kind){return kind==='Bounded customisation'?'Simple custom order':kind;}
function paymentLabel(payment){return payment?.includes('30-day')?'Existing supplier: pay in 30 days':payment==='Advance is workable'?'Pay before dispatch':payment;}
function statusLabel(status){return status==='Awaiting capacity'?'Awaiting stock confirmation':status;}
function formatDate(s){return new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});}
function requestForm(){return pageHead('Tell us what you need','Give suppliers a clear product list so they can reply with the right price and terms. Start with products already in stock.')+`<div class="split"><form class="panel" id="request-form"><div class="form-grid"><label class="field wide">What are you buying?<input name="name" required maxlength="90" value="Cotton towels for my shop"></label><label class="field">Category<select name="category">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Type of purchase<select name="kind"><option>Ready stock</option><option value="Bounded customisation">Simple custom order</option></select></label><label class="field">Required quantity<input name="qty" type="number" min="1" max="10000" value="200" required><small>Use the quantity you can actually sell.</small></label><label class="field">Budget per unit (₹)<input name="budget" type="number" min="1" max="100000" value="100" required></label><label class="field">Required by<input name="date" type="date" value="2026-10-25" min="2026-10-05" required></label><label class="field">Payment needs<select name="payment"><option value="Advance is workable">I can pay before dispatch</option><option value="Need existing 30-day supplier credit">I need 30 days to pay an existing supplier</option></select></label><label class="field wide">Material, size, colours and finish<textarea name="spec" minlength="20" required maxlength="1200">100% cotton, 500 GSM, 70 × 140 cm, sage green. New unused stock, same colour and weight. Sample needed before bulk purchase.</textarea><small>For a custom order, describe one product and the change you want, such as a simple print. Include material, size and finish, not just a photo.</small></label><label class="field wide">What does this purchase cost you today? (₹)<input name="baseline" type="number" min="0" max="10000000" value="20800"><small>Optional. Include products, delivery and the cost of paying earlier. Leave 0 if unknown; no saving will be shown.</small></label></div><div class="form-actions">${button('Cancel','nav','data-view="requests"','secondary')}<button class="btn" type="submit">Send demo request ${ico('arrow')}</button></div></form><aside class="panel"><h3>Help the supplier understand your order</h3><div class="checklist"><div class="inline-note">${ico('check')}Material, size, colour and quantity</div><div class="inline-note">${ico('check')}The date you need the products</div><div class="inline-note">${ico('check')}When you can pay</div><div class="inline-note">${ico('check')}Sample approval before a custom order</div></div><div class="notice" style="margin-top:25px">This request appears immediately in the seller demo. Switch roles to quote it. No information is sent to real suppliers.</div></aside></div>`;}
function quoteCost(r,q){const goods=r.qty*q.price+q.setup,credit=q.days>=30?0:goods*.18*30/365,fee=serviceFee();return {goods,credit,fee,payable:goods+q.freight+q.sample+fee,total:goods+q.freight+q.sample+fee+q.loss+credit};}
function eligible(r,q){return q.moq<=r.qty&&q.stock>=r.qty&&!(r.payment.includes('30-day')&&q.days<30);}
function compareView(){const r=request();if(!r)return requestsView();const feasible=r.quotes.filter(q=>eligible(r,q));const best=feasible.length?Math.min(...feasible.map(q=>quoteCost(r,q).total)):0;return pageHead('Compare the total cost','A cheaper unit can still be a worse purchase. Compare the right quantity, quality, delivery date and payment terms.',button('My requests','nav','data-view="requests"','secondary small'))+`<div class="panel"><div class="request-row"><div class="thumb">${pic(r.productId)}</div><div class="info"><span class="badge pink">${esc(kindLabel(r.kind))} · ${r.id}</span><h2>${esc(r.name)}</h2><p>${r.qty} units · Need by ${formatDate(r.date)} · ${esc(paymentLabel(r.payment))}</p></div></div><p>${esc(r.spec)}</p><div class="compare-heading"><label class="field">Your current total purchase cost (₹)<input id="baseline" type="number" min="0" max="10000000" value="${r.baseline}" aria-label="Current total purchase cost"></label><div class="actions">${button('Ask a question '+ico('message'),'messages',`data-id="${r.id}"`,'secondary small')}${r.quotes.length?button('Export comparison '+ico('download'),'exportquotes',`data-id="${r.id}"`,'secondary small'):''}</div></div><label class="comparison-option"><input id="credit-required" type="checkbox" ${r.payment.includes('30-day')?'checked':''}>I need 30 days to pay my existing supplier</label><p class="definition">The credit option assumes an existing supplier relationship. “Cost of paying earlier” estimates the extra cash tied up for 30 days at 18% a year. Possible losses are an estimate. Neither estimate is collected as a fee.</p></div>${r.quotes.length?`<div class="quote-grid" id="tour-target">${r.quotes.map(q=>{const c=quoteCost(r,q),fit=eligible(r,q),save=r.baseline-c.total,isBest=fit&&Math.abs(c.total-best)<.01;return `<article class="quote ${isBest?'best':''}"><div><span class="badge ${isBest?'pink':fit?'green':'amber'}">${isBest?'Lowest total cost that fits':fit?'Fits your quantity and payment needs':'Does not fit this request'}</span><h3 style="margin-top:12px">${esc(q.supplier)}</h3><p style="font-size:12px;margin:5px 0">${esc(q.type)} · Demo business</p><div class="spec-line">Minimum ${q.moq} units · dispatch in ${q.lead} days<br>${q.days?`${q.days}-day existing credit`:'Advance payment'} · ${q.stock} units available</div><p style="font-size:12px">${esc(q.note)}</p></div><div class="receipt"><div><span>Products + setup</span><strong>${money(c.goods)}</strong></div><div><span>Delivery</span><strong>${money(q.freight)}</strong></div><div><span>Sample</span><strong>${money(q.sample)}</strong></div><div><span>Buying help fee</span><strong>${money(c.fee)}</strong></div><div><span>Cost of paying earlier (estimate)</span><strong>${money(c.credit)}</strong></div><div><span>Possible losses (estimate)</span><strong>${money(q.loss)}</strong></div><div class="total"><span>Estimated total cost</span><span>${money(c.total)}</span></div>${r.baseline>0?`<div><span>${save>=0?'Estimated saving':'More than your current purchase'}</span><strong style="color:${save>=0?'#24694e':'#a43948'}">${money(Math.abs(save))} (${(Math.abs(save)/r.baseline*100).toFixed(1)}%)</strong></div>`:'<small>Add your current cost to see a saving.</small>'}<small>Demo bill: ${money(c.payable)}. The two estimates above are not charged.</small></div><button class="btn ${isBest?'':'secondary'}" data-action="selectquote" data-request="${r.id}" data-quote="${q.id}" ${!fit?'disabled':''}>${fit?'Review this quote':'Does not meet your needs'}</button></article>`;}).join('')}</div><div class="notice" style="margin-top:20px">These are example offers and costs. A factory may be cheaper; a wholesaler may offer smaller quantities or more time to pay. Choose the option that fits the whole purchase.</div>`:empty('Waiting for a supplier price','Switch to seller to send a price offer, or add example offers to try the comparison.','Switch to seller','feed')+button('Add example supplier offers','seedquotes',`data-id="${r.id}"`,'secondary')}<section class="panel section">${serviceChoices()}</section>`;}
function plansView(){return pageHead('Choose how to pay for buying help','A buying job is one purchase: confirm the list, compare costs, agree terms, track delivery and check receipt. Browsing is free.')+`<div class="plan-grid" id="tour-target"><section class="panel"><span class="badge pink">Start with one purchase</span><h2 style="margin-top:15px">Pay per buying job</h2><div class="plan-price">₹349 <small>/ buying job</small></div><p>Pay for one agreed purchase. No monthly commitment; the fee is separate from products and delivery.</p><ul><li>Compare supplier prices and total cost</li><li>Confirm products, quantity and terms</li><li>Track delivery and check what arrives</li></ul>${button(state.plan==='peruse'?'Current demo choice':'Choose pay per job','plan','data-plan="peruse"','secondary full')}</section><section class="panel"><span class="badge">For regular purchases</span><h2 style="margin-top:15px">Monthly plan</h2><div class="plan-price">₹1,199 <small>/ month · up to 4 jobs</small></div><p>Four per-use jobs cost ₹1,396. A monthly plan saves ₹197 at that frequency.</p><ul><li>The same complete buying job</li><li>Up to four buying jobs per month</li><li>Extra jobs: ₹349 each, optional</li></ul>${button(state.plan==='monthly'?`Demo active · ${state.planUsed}/4 jobs used`:'Try the demo monthly plan','plan','data-plan="monthly"','full')}</section></div><div class="panel section"><h3>Which plan costs less for you?</h3><div class="table-wrap"><table><thead><tr><th>Jobs per month</th><th>Pay per job</th><th>Monthly plan</th><th>Cheaper option</th></tr></thead><tbody><tr><td>1</td><td>₹349</td><td>₹1,199</td><td>Pay per job</td></tr><tr><td>3</td><td>₹1,047</td><td>₹1,199</td><td>Pay per job</td></tr><tr><td>4</td><td>₹1,396</td><td>₹1,199</td><td>Monthly, by ₹197</td></tr></tbody></table></div><div class="notice" style="margin-top:20px">Prices are proposed for testing and include an 18% reference tax; the final tax treatment needs confirmation. Products, samples and delivery cost extra. Custom production needs a separate price. No loan, delivery guarantee or stock buyback is included.</div></div>`;}
function supplierHome(){const own=state.products.filter(p=>p.supplier==='Panipat Loomworks');return pageHead('Match your stock to a shop’s needs.','Welcome to Panipat Loomworks. See what shops want, send your price and terms, and pay zero sales commission.',button('Add a stock listing '+ico('plus'),'listing','','secondary'))+`<section class="hero"><div class="hero-copy"><h1>Clear product lists.<br>Easier price offers.</h1><p>See the material, size, colour, quantity, date and payment needs before sending a price.</p>${button('See what shops need '+ico('arrow'),'nav','data-view="feed"')}</div><div class="hero-image">${pic(0)}<div class="floating">${ico('check')}0% supplier sales commission</div></div></section><div class="stats"><div class="stat"><span>Demo stock listings</span><strong>${own.filter(p=>p.active).length}</strong></div><div class="stat"><span>Buyer requests</span><strong>${state.requests.length}</strong></div><div class="stat"><span>Orders in this session</span><strong>${state.orders.length}</strong></div><div class="stat"><span>Sales commission</span><strong>₹0</strong></div></div><div class="split"><section class="panel" id="tour-target"><h2>Ready to quote</h2>${state.requests.slice(0,2).map(r=>`<div class="request-row">${pic(r.productId,'thumb')}<div class="info"><h3>${esc(r.name)}</h3><p>${r.qty} units · ${esc(kindLabel(r.kind))}</p>${button('View request and send price','quoteform',`data-id="${r.id}"`,'secondary small')}</div></div>`).join('')}</section><section class="panel"><h3>You decide what you can supply</h3><p style="margin-top:12px">Saving a request does not accept an order. Set your minimum quantity, price, payment terms and dispatch time. Confirm stock after the buyer chooses your offer.</p><div class="notice" style="margin-top:20px">You supply the products. The shop can pay Merchant separately for buying help. Listing products and sending prices carry zero sales commission in this proposal.</div></section></div>`;}
function feedView(){const list=state.requests.filter(r=>!state.feedPassed.includes(r.id));return pageHead('What shops want to buy','Read a shop’s product list. Save it, skip it or send a price. You confirm stock only after the shop chooses your offer.')+`<div class="spread" style="margin-bottom:20px"><span class="swipe-summary">${list.length} requests · <span class="saved-count">${state.feedSaved.length} saved</span></span>${button('Show skipped requests','restorefeed','','quiet small')}</div><section class="feed" id="tour-target">${list.map(r=>`<article class="demand-card"><div class="demand-head">${pic(r.productId)}<div><span class="badge ${r.kind==='Ready stock'?'green':'amber'}">${esc(kindLabel(r.kind))}</span><h3 style="margin-top:8px">${esc(r.name)}</h3><p style="font-size:12px;margin-top:5px">Buyer ${r.id.replace('REQ','BUY')} · Karnal</p></div></div><div class="demand-body"><p style="font-size:13px">${esc(r.spec)}</p><div class="demand-meta"><div><span>Quantity needed</span><strong>${r.qty} units</strong></div><div><span>Budget / unit</span><strong>${money(r.budget)} approx.</strong></div><div><span>Needed by</span><strong>${formatDate(r.date)}</strong></div><div><span>Payment needs</span><strong>${r.payment.includes('30')?'Existing 30-day credit':'Pay before dispatch'}</strong></div></div><div class="inline-note">${ico('shield')}Product list ready · order not confirmed</div><div class="demand-actions" style="margin-top:20px">${button('Skip','passrequest',`data-id="${r.id}"`,'quiet small')}${button(ico('heart')+(state.feedSaved.includes(r.id)?'Saved':'Save'),'saverequest',`data-id="${r.id}"`,'secondary small')}${button('Send a price offer '+ico('arrow'),'quoteform',`data-id="${r.id}"`,'small')}</div><button class="text-link" data-action="messages" data-id="${r.id}">Ask about the product details</button></div></article>`).join('')}</section>${!list.length?empty('No more requests to show','Show skipped requests or switch to buyer to publish a new requirement.','Buyer view','newrequest'):''}`;}
function inventoryView(){const own=state.products.filter(p=>p.supplier==='Panipat Loomworks');return pageHead('Your products in stock','Panipat Loomworks is the example stock owner here. Listing changes appear immediately on the buyer side.',button('Add listing '+ico('plus'),'listing'))+`<section class="panel" id="tour-target">${own.map(p=>`<div class="inventory-row">${pic(p.id)}<div><h3>${esc(p.name)}</h3><p>${esc(p.spec)} · Minimum ${p.moq} units</p><p class="mobile-inventory-meta">${money(p.price)}/unit · ${p.stock} units available</p><span class="badge ${p.active?'green':'amber'}">${p.active?'Visible to buyers':'Paused'}</span></div><div class="price" style="font-size:18px">${money(p.price)}<small>/unit</small></div><div class="stock-num"><strong>${p.stock}</strong><p>in stock</p></div><div class="actions">${button(ico('edit'),'listing',`data-id="${p.id}" aria-label="Edit ${esc(p.name)}"`,'secondary small')}${button(p.active?'Pause':'Resume','togglelisting',`data-id="${p.id}"`,'quiet small')}</div></div>`).join('')}</section>`;}
function myQuotes(){const qs=state.requests.flatMap(r=>r.quotes.filter(q=>q.supplier==='Panipat Loomworks').map(q=>({r,q})));return pageHead('Your submitted quotes','Your terms remain private to the buyer in this demo. A quote is not a confirmed goods order.')+`<section class="panel">${qs.length?qs.map(({r,q})=>`<div class="request-row"><div class="info"><span class="badge">${q.id} · ${r.id}</span><h3>${esc(r.name)}</h3><p>${money(q.price)}/unit · MOQ ${q.moq} · ${q.lead} days · ${q.days?q.days+'-day terms':'Advance'}</p></div>${button('Review buyer view','buyercompare',`data-id="${r.id}"`,'secondary small')}</div>`).join(''):empty('No submitted quotes','Find a requirement you can actually supply and prepare a complete quote.','Explore requests','feed')}</section>`;}
function orderStage(o){return ['Awaiting capacity','Confirmed','Packed','Dispatched','Received'].indexOf(o.status);}
function ordersView(){return pageHead(role==='buyer'?'Your purchases, step by step':'Orders to prepare and send',role==='buyer'?'Follow your order, check what arrives and report missing, damaged or incorrect products. Product payments and the buying help fee are separate.':'This seller demo covers all listed suppliers. Confirm stock, mark products packed and send them in the demo. Shops see each update.')+`<section class="panel" id="tour-target">${state.orders.length?state.orders.map(o=>`<article class="order-block"><div class="spread"><div><div class="order-title"><h3>${esc(o.title)}</h3><span class="badge ${o.status==='Received'?'green':'pink'}">${esc(statusLabel(o.status))}</span>${o.issue?'<span class="badge amber">Issue recorded</span>':''}</div><p style="font-size:13px;margin-top:5px">${o.id} · ${esc(o.supplier)} · ${o.qty} units · ${money(o.payable)} demo payable</p></div>${button('Order details','orderdetail',`data-id="${o.id}"`,'secondary small')}</div><div class="timeline">${['Awaiting capacity','Confirmed','Packed','Dispatched','Received'].map((s,i)=>`<div class="milestone ${orderStage(o)>=i?'done':''}"><span class="dot">${orderStage(o)>=i?ico('check'):i+1}</span>${statusLabel(s)}</div>`).join('')}</div><div class="actions">${role==='seller'&&orderStage(o)<3?button(['Confirm stock','Mark packed','Mark dispatched (demo)'][Math.max(0,orderStage(o))],'advanceorder',`data-id="${o.id}"`,'small'):''}${role==='buyer'&&o.status==='Dispatched'?button('Record received goods','receive',`data-id="${o.id}"`,'small'):''}${role==='buyer'&&['Dispatched','Received'].includes(o.status)?button('Report a problem','issue',`data-id="${o.id}"`,'secondary small'):''}${role==='buyer'&&o.status==='Received'?button('Buy these products again','reorder',`data-id="${o.id}"`,'secondary small'):''}</div>${o.issue?`<p class="notice amber" style="margin-top:15px">${esc(o.issue)} · Pending review; no refund is promised.</p>`:''}</article>`).join(''):empty('Your first demo order will appear here','Choose products or compare supplier offers. Switch to seller to confirm stock, pack and send the demo order.','Browse '+(role==='buyer'?'stock':'requests'),role==='buyer'?'home':'feed')}</section>`;}
function render(){const app=document.getElementById('app');if(!role){app.innerHTML=header()+landing();return;}let content=role==='buyer'?(view==='home'?catalogue(true):view==='cart'?cartView():view==='requests'?requestsView():view==='newrequest'?requestForm():view==='compare'?compareView():view==='plans'?plansView():ordersView()):(view==='home'?supplierHome():view==='feed'?feedView():view==='inventory'?inventoryView():view==='quotes'?myQuotes():ordersView());app.innerHTML=header()+`<div class="shell">${sidebar()}<main class="main" id="main">${content}<div class="demo-footer">Meesho Merchant concept · Example products, prices and orders · No real transactions</div></main></div>`+mobileNav();if(tourStep>=0)renderTour();}
function showModal(title,body,narrow=false){modalFocus=document.activeElement;const root=document.getElementById('overlay');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">${ico('close')}</button></header>${body}</section></div>`;const focus=root.querySelector('input,select,textarea,button');focus?.focus();}
function closeModal(){document.getElementById('overlay').innerHTML='';modalFocus?.focus();modalFocus=null;}
function showProduct(id){const p=product(id);showModal('Product details and quantity prices',`<div class="detail-hero">${pic(p.id)}<div><span class="badge green">New unused stock · Demo listing</span><h2 style="margin-top:15px">${esc(p.name)}</h2><p>${esc(p.supplier)} · ${esc(p.type)}</p><div class="specs"><div><span>Product details</span>${esc(p.spec)}</div><div><span>Colour</span>${esc(p.colour)}</div><div><span>Minimum quantity</span>${p.moq} units</div><div><span>Available stock</span>${p.stock} units</div><div><span>Origin</span>Panipat / Karnal</div><div><span>Sample and problem handling</span>Confirm before order</div></div><p style="font-size:13px">Photos show example products. Cushion covers do not include inserts. Check the sample and written product details before buying.</p>${quantityWidget(p,p.moq,'product')}<div class="actions">${button(`Add ${p.moq} units to basket`,'addselected',`data-id="${p.id}" data-qty="${p.moq}"`)}${button('Request a different size or finish','customproduct',`data-id="${p.id}"`,'secondary')}</div></div></div>`);}
function quoteForm(id){const r=request(id);showModal('Send your price and terms',`<p class="lead">${esc(r.name)} · ${r.qty} units · ${esc(paymentLabel(r.payment))}</p><div class="notice" style="margin-bottom:20px">${esc(r.spec)}<br>Sending a price does not accept the order. The shop chooses an offer; you then confirm stock.</div><form id="quote-form" data-id="${r.id}"><div class="form-grid"><label class="field">Unit price (₹)<input name="price" type="number" min="1" max="100000" step=".01" value="${r.budget*.9}" required></label><label class="field">Minimum quantity (units)<input name="moq" type="number" min="1" max="10000" value="${r.qty}" required></label><label class="field">Quantity you can supply<input name="stock" type="number" min="1" max="100000" value="${Math.max(r.qty,500)}" required></label><label class="field">Days until dispatch<input name="lead" type="number" min="1" max="90" value="5" required></label><label class="field">Delivery charge (₹)<input name="freight" type="number" min="0" max="100000" value="600" required></label><label class="field">Sample cost (₹)<input name="sample" type="number" min="0" max="100000" value="150" required></label><label class="field">Custom setup cost (₹)<input name="setup" type="number" min="0" max="100000" value="${r.kind==='Ready stock'?0:1500}" required></label><label class="field">Payment terms<select name="days"><option value="0">Pay before dispatch</option><option value="30">Existing supplier: pay in 30 days</option></select></label><label class="field wide">Product match, changes and how problems will be handled<textarea name="note" required minlength="10" maxlength="1000">Can supply the specified material, dimensions and quantity. Price offer valid for 7 days. Report damaged or missing items within 5 days for review; no unsold-stock buyback.</textarea></label><label class="comparison-option wide"><input name="requiresSample" type="checkbox" checked>Sample approval required before bulk goods order</label></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn">Submit demo quote</button></div></form>`);}
function reviewQuote(rid,qid){const r=request(rid),q=r.quotes.find(q=>q.id===qid);if(!eligible(r,q))return toast('This quote does not meet the current quantity or credit requirement.');const c=quoteCost(r,q);showModal('Review before the bulk order',`<p class="lead">${esc(q.supplier)} · ${r.qty} units · ${esc(r.name)}</p><div class="notice">Supplier legal identity: ${esc(q.supplier)}, demo business, Panipat/Karnal. In a live purchase, identity and binding written terms must be checked before goods payment.</div><div class="receipt"><div><span>Products including setup</span><strong>${money(c.goods)}</strong></div><div><span>Delivery</span><strong>${money(q.freight)}</strong></div><div><span>Sample</span><strong>${money(q.sample)}</strong></div><div><span>Optional buying help fee</span><strong>${money(c.fee)}</strong></div><div class="total"><span>Demo payable</span><strong>${money(c.payable)}</strong></div></div>${q.requiresSample&&r.approvedQuote!==q.id?`<div class="notice amber"><strong>Sample approval comes first</strong>Approve the sample’s material, size, colour and finish before placing a bulk demo order.</div><div class="actions">${button('Check the sample (demo)','sample',`data-request="${r.id}" data-quote="${q.id}"`,'full')}</div>`:`<div class="notice green"><strong>${q.requiresSample?'Sample approved for these product details':'Ready stock · sample not required by this quote'}</strong>The supplier confirms stock next. No real payment is taken.</div><div class="actions">${button('Place simulated goods order','placequote',`data-request="${r.id}" data-quote="${q.id}"`,'full')}</div>`}<p class="definition">Products → supplier; delivery → carrier; buying help fee → Merchant. Estimated losses and the cost of paying earlier are not charged. No real payments or credit approvals happen here.</p>`,true);}
function sampleModal(rid,qid){showModal('Check and approve the sample',`<p class="lead">Check the sample’s material, size, colour and finish before ordering the full quantity.</p><form id="sample-form" data-request="${rid}" data-quote="${qid}"><div class="checklist"><label><input type="checkbox" required>Material and fabric weight (GSM) match the request</label><label><input type="checkbox" required>Dimensions, colour and finish match</label><label><input type="checkbox" required>Quantity, sample cost and how problems are handled are agreed</label></div><p class="definition">Simulated approval only. No real sample has been checked.</p><div class="form-actions"><button class="btn" type="submit">Record demo sample approval</button></div></form>`,true);}
function checkoutCart(){const t=cartTotals();showModal('Review your demo purchase',`<p class="lead">${state.cart.length} product lines · ${state.cart.reduce((s,c)=>s+c.qty,0)} units</p><div class="receipt"><div><span>Products</span><strong>${money(t.goods)}</strong></div><div><span>Delivery estimate</span><strong>${money(t.freight)}</strong></div><div><span>Optional buying help fee</span><strong>${money(t.fee)}</strong></div><div class="total"><span>Demo payable</span><strong>${money(t.total)}</strong></div></div><div class="notice">Supplier identities and separate goods invoices are shown in the order. No real payment, stock reservation or purchase occurs.</div><div class="actions">${button('Place simulated order','placecart','','full')}</div>`,true);}
function addCart(id){const p=product(id);if(!p.active)return toast('This listing is paused.');let c=state.cart.find(c=>c.id===p.id);if((c?.qty||0)+p.moq>p.stock)return toast('That quantity exceeds the listed demo stock.');if(c)c.qty+=p.moq;else state.cart.push({id:p.id,qty:p.moq});persist();closeModal();render();toast(`${p.moq} units added. Open My basket to review.`);}
function createOrder(data){const o={id:'MM-'+(1001+state.orders.length),status:'Awaiting capacity',date:new Date().toISOString(),issue:'',managed:state.service==='managed',...data};state.orders.unshift(o);if(o.managed&&state.plan==='monthly'&&state.planUsed<4)state.planUsed++;persist();navigate('orders');toast('Demo order created. Switch to seller to confirm stock.');}
function listingModal(id){const p=id!==undefined?product(id):null;showModal(p?'Edit ready stock':'List ready stock',`<form id="listing-form" ${p?`data-id="${p.id}"`:''}><div class="form-grid"><label class="field wide">Product name<input name="name" maxlength="80" required value="${esc(p?.name||'Cotton kitchen towel')}" ></label><label class="field">Category<select name="category">${categories.slice(1).map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Price per unit (₹)<input name="price" type="number" min="1" max="100000" value="${p?.price||45}" required></label><label class="field">Minimum quantity<input name="moq" type="number" min="1" max="10000" value="${p?.moq||50}" required></label><label class="field">Available units<input name="stock" type="number" min="1" max="100000" value="${p?.stock||500}" required></label><label class="field wide">Material, dimensions and finish<input name="spec" maxlength="150" value="${esc(p?.spec||'40 × 60 cm · 100% cotton')}" required></label><label class="field">Colour<input name="colour" maxlength="40" value="${esc(p?.colour||'Natural')}" required></label><label class="field">Demo photo<select name="photo"><option value="5">Kitchen towel</option><option value="0">Bath towel</option><option value="12">Cushion cover</option><option value="18">Table runner</option></select></label></div><fieldset class="tier-settings"><legend>Prices for larger quantities</legend><p class="definition">The base price applies at the minimum quantity. Set discounts for larger orders. Each discount applies to every unit; buyers only see quantities you have in stock.</p><div class="form-grid">${[2,4,8].map((multiple,i)=>`<label class="field">${multiple} × minimum: discount %<input name="discount${multiple}" type="number" min="0" max="30" step="0.1" value="${(p?.discounts||[0,3,6,8])[i+1]}" required></label>`).join('')}</div></fieldset><div class="notice" style="margin-top:18px">List new, unused products for this pilot. Returned or damaged products need separate checks. This is an example listing, not verified stock.</div><div class="form-actions"><button class="btn" type="submit">Save demo listing</button></div></form>`,true);}
function messagesModal(id){const r=request(id);showModal('Ask about this purchase',`<p class="lead">${esc(r.name)} · In-demo messages only</p><div class="inbox">${r.messages.map(m=>`<div class="message ${m.by===role?'mine':''}"><small>${esc(m.by)}</small>${esc(m.text)}</div>`).join('')||'<p>No messages yet. Ask about material, size, packaging or timing.</p>'}</div><form id="message-form" data-id="${r.id}" style="margin-top:20px"><label class="field">Your product question<textarea name="message" required minlength="3" maxlength="500" placeholder="Can you confirm the finished dimensions and packing units?"></textarea></label><p class="definition">Keep clarification here. Direct email/phone sharing is flagged in this demo; supplier legal identity remains visible before a purchase.</p><div class="form-actions"><button class="btn" type="submit">Send demo message</button></div></form>`,true);}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);showModal(o.id+' · Order record',`<p class="lead">${esc(o.title)} · ${esc(statusLabel(o.status))}</p><div class="notice">${esc(o.supplier)} · Demo supplier(s), Panipat/Karnal. Products invoice(s) are issued by each supplier. Merchant's buying help fee has a separate record.</div><div class="receipt"><div><span>Products</span><strong>${money(o.goods)}</strong></div><div><span>Delivery</span><strong>${money(o.freight)}</strong></div><div><span>Sample</span><strong>${money(o.sample||0)}</strong></div><div><span>Buying help fee</span><strong>${money(o.fee)}</strong></div><div class="total"><span>Demo payable</span><strong>${money(o.payable)}</strong></div></div><p>${o.managed?'Merchant buying help selected.':'Buyer handles the purchase directly.'} ${o.fee===0&&o.managed?'Buying job included in your demo monthly plan.':''}</p><div class="actions">${button('Download demo order record '+ico('download'),'downloadorder',`data-id="${o.id}"`,'secondary full')}</div><p class="definition">This record is not a tax invoice, payment receipt or evidence of actual dispatch.</p>`,true);}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

