function startTour(){clearTimeout(window.toastTimer);document.getElementById('toast').classList.remove('visible');tourStep=0;advanceTour(0);}
function advanceTour(delta){const steps=role==='buyer'?buyerTour:sellerTour;tourStep+=delta;if(tourStep>=steps.length){tourStep=-1;if(!state.toured.includes(role))state.toured.push(role);persist();render();toast('You’re ready to explore. Replay Walkthrough anytime.');return;}if(tourStep<0)tourStep=0;view=steps[tourStep][0];if(view==='compare')selectedRequest='REQ-101';if(role==='buyer'&&view==='cart'&&!state.cart.length){state.cart=[{id:0,qty:200}];persist();}closeModal();render();const target=tourTarget();if(target){const r=target.getBoundingClientRect();const top=window.scrollY+r.top-(window.innerWidth<=760?85:115);window.scrollTo({top:Math.max(0,top),behavior:'instant'});}else window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(positionTour);}
function tourTarget(){const steps=role==='buyer'?buyerTour:sellerTour;const selector=steps[tourStep]?.[3];if(!selector)return null;return [...document.querySelectorAll(selector)].find(el=>el.getBoundingClientRect().width>0)??document.querySelector('#main .panel, #main .hero');}
function renderTour(){const steps=role==='buyer'?buyerTour:sellerTour,s=steps[tourStep];if(!s)return;document.getElementById('app').insertAdjacentHTML('beforeend',`<div class="tour-spotlight" aria-hidden="true"></div><aside class="tour" aria-label="${role} walkthrough"><div class="tour-top"><span>${role==='buyer'?'Buyer':'Supplier'} walkthrough · ${tourStep+1} of ${steps.length}</span><button class="close" data-action="tourstop" aria-label="Exit walkthrough">${ico('close')}</button></div><h3>${s[1]}</h3><p>${s[2]}</p><div class="tour-progress">${steps.map((_,i)=>`<span class="${i<=tourStep?'on':''}"></span>`).join('')}</div><div class="tour-foot">${button(tourStep?'Back':'Explore on my own',tourStep?'tourback':'tourstop','','quiet small')}${button(tourStep===steps.length-1?'Finish walkthrough':'Next '+ico('arrow'),'tournext','','small')}</div></aside>`);requestAnimationFrame(positionTour);}
function positionTour(){const guide=document.querySelector('.tour'),ring=document.querySelector('.tour-spotlight'),target=tourTarget();if(!guide||!ring||!target)return;const r=target.getBoundingClientRect(),w=innerWidth,h=innerHeight,mobile=w<=760,pad=6;const inHeader=!!target.closest('.topbar'),top=Math.max(inHeader?4:72,r.top-pad),bottom=Math.min(h-(mobile?72:12),r.bottom+pad);ring.style.cssText=`left:${Math.max(4,r.left-pad)}px;top:${top}px;width:${Math.min(w-8,r.width+pad*2)}px;height:${Math.max(0,bottom-top)}px`;guide.style.bottom='auto';const gh=guide.offsetHeight,gw=guide.offsetWidth;let x,y;if(mobile){x=12;y=Math.min(h-gh-80,Math.max(82,r.bottom+16));if(y<r.bottom+10&&r.top-gh-16>=76)y=r.top-gh-16;}else{if(r.right+gw+24<w){x=r.right+18;y=Math.max(82,Math.min(r.top,h-gh-16));}else if(r.left-gw-24>0){x=r.left-gw-18;y=Math.max(82,Math.min(r.top,h-gh-16));}else{x=w-gw-24;y=r.bottom+18;if(y+gh>h-16)y=Math.max(82,r.top-gh-18);}}guide.style.left=x+'px';guide.style.right='auto';guide.style.top=y+'px';}
let tourFrame;for(const event of ['resize','scroll'])window.addEventListener(event,()=>{if(tourStep<0)return;cancelAnimationFrame(tourFrame);tourFrame=requestAnimationFrame(positionTour);},{passive:true});
function enter(next){role=next;view='home';tourStep=-1;render();if(!state.toured.includes(next))startTour();}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'enter':enter(b.dataset.role);break;case'landing':role=null;tourStep=-1;closeModal();render();break;case'nav':tourStep=-1;navigate(b.dataset.view);break;case'switch':tourStep=-1;closeModal();enter(role==='buyer'?'seller':'buyer');break;case'close':closeModal();break;case'tour':closeModal();startTour();break;case'tournext':advanceTour(1);break;case'tourback':advanceTour(-1);break;case'tourstop':tourStep=-1;if(!state.toured.includes(role))state.toured.push(role);persist();render();break;case'filter':filter=b.dataset.category;onlySaved=false;render();break;case'clearfilters':filter='All products';query='';onlySaved=false;render();break;case'saved':onlySaved=!onlySaved;render();break;case'save':{const n=Number(id);state.saved=state.saved.includes(n)?state.saved.filter(x=>x!==n):[...state.saved,n];persist();render();break;}case'product':showProduct(id);break;case'add':addCart(id);break;case'addselected':{const p=product(id),qty=Number(b.dataset.qty),c=state.cart.find(c=>c.id===p.id);if((c?.qty||0)+qty>p.stock)return toast('Combined basket quantity exceeds available stock.');if(c)c.qty+=qty;else state.cart.push({id:p.id,qty});persist();closeModal();render();toast(qty+' units added. Open My basket to review quantity pricing.');break;}case'tierqty':setQuantity(b.closest('.quantity-pricing'),b.dataset.qty);break;case'remove':state.cart=state.cart.filter(c=>c.id!==Number(id));persist();render();break;case'qty':{const c=state.cart.find(c=>c.id===Number(id)),p=product(id),q=c.qty+Number(b.dataset.delta);if(q<p.moq)return toast('Use Remove to remove the product. Minimum is '+p.moq+' units.');if(q>p.stock)return toast('Quantity exceeds the available demo stock.');c.qty=q;persist();render();break;}case'compare':selectedRequest=id;navigate('compare');break;case'customproduct':{const p=product(id);navigate('newrequest');const f=document.getElementById('request-form');f.elements.namedItem('name').value=p.name+' · my specification';f.elements.namedItem('category').value=p.category;f.elements.namedItem('spec').value=p.spec+', '+p.colour+'. Confirm usable quantity and exact finish.';f.elements.namedItem('qty').value=p.moq;f.elements.namedItem('budget').value=p.price;f.elements.namedItem('baseline').value=0;break;}case'seedquotes':{const r=request(id);const p=r.budget*.9;r.quotes=[{id:'Q-'+Date.now(),supplier:'Panipat Loomworks',type:'Manufacturer',price:p,moq:r.qty,freight:600,sample:150,setup:r.kind==='Ready stock'?0:1500,loss:200,days:0,lead:5,stock:r.qty*3,note:'Illustrative sample quote, not a supplier response. Exact specifications require sample approval.',requiresSample:true,confirmed:true},{id:'Q-'+(Date.now()+1),supplier:'Karnal Home Wholesale',type:'Wholesaler',price:r.budget*.97,moq:Math.min(50,r.qty),freight:300,sample:0,setup:r.kind==='Ready stock'?0:1800,loss:100,days:30,lead:3,stock:r.qty*2,note:'Illustrative quote with assumed existing credit. No approval is implied.',requiresSample:r.kind!=='Ready stock',confirmed:true}];r.status='Quotes ready';persist();render();break;}case'quoteform':quoteForm(id);break;case'buyercompare':role='buyer';selectedRequest=id;tourStep=-1;navigate('compare');break;case'selectquote':reviewQuote(b.dataset.request,b.dataset.quote);break;case'sample':sampleModal(b.dataset.request,b.dataset.quote);break;case'placequote':{const r=request(b.dataset.request),q=r.quotes.find(q=>q.id===b.dataset.quote);if(!eligible(r,q)||q.requiresSample&&r.approvedQuote!==q.id)return toast('Please resolve quote fit and sample approval first.');const c=quoteCost(r,q);r.status='Order placed';createOrder({title:r.name,supplier:q.supplier,qty:r.qty,goods:c.goods,freight:q.freight,sample:q.sample,fee:c.fee,payable:c.payable,items:[{id:r.productId,qty:r.qty}],requestId:r.id});break;}case'checkoutcart':if(state.cart.length)checkoutCart();break;case'placecart':{if(!state.cart.length)return;const invalid=state.cart.some(c=>!product(c.id)?.active||c.qty<product(c.id).moq||c.qty>product(c.id).stock);if(invalid)return toast('A listing changed. Review minimums, visibility and stock before ordering.');const t=cartTotals(),items=structuredClone(state.cart);state.cart=[];createOrder({title:items.length===1?product(items[0].id).name:'Mixed home-textile basket',supplier:[...new Set(items.map(c=>product(c.id).supplier))].join(' + '),qty:items.reduce((s,c)=>s+c.qty,0),goods:t.goods,freight:t.freight,sample:0,fee:t.fee,payable:t.total,items});break;}case'plan':{if(b.dataset.plan==='monthly'){showModal('Try the monthly plan in this demo',`<p>₹1,199 per demo month covers up to four buying jobs. Products, freight and samples remain separate. There is no real billing or automatic renewal.</p><div class="notice" style="margin-top:18px">This restarts the demo plan with four included jobs. No payment is taken.</div><div class="actions">${button('Start demo ₹1,199 plan','activateplan','','full')}</div>`,true);}else{state.plan='peruse';persist();render();toast('Per-use selected. No monthly plan is needed.');}break;}case'activateplan':state.plan='monthly';state.planUsed=0;state.service='managed';persist();closeModal();render();toast('Simulated monthly plan activated. No money charged.');break;case'listing':listingModal(id===undefined?undefined:Number(id));break;case'togglelisting':{const p=product(id);p.active=!p.active;persist();render();toast(p.active?'Listing is visible to buyers.':'Listing paused in buyer discovery.');break;}case'passrequest':state.feedPassed.push(id);persist();render();break;case'saverequest':state.feedSaved=state.feedSaved.includes(id)?state.feedSaved.filter(x=>x!==id):[...state.feedSaved,id];persist();render();break;case'restorefeed':state.feedPassed=[];persist();render();break;case'messages':messagesModal(id);break;case'advanceorder':{const o=state.orders.find(o=>o.id===id);o.status=['Confirmed','Packed','Dispatched'][Math.max(0,orderStage(o))]||o.status;persist();render();toast('Demo milestone updated. The buyer sees the same status.');break;}case'receive':showModal('Record received goods',`<form id="receive-form" data-id="${id}"><p>Count the products and check material, size, colour and condition. This records a demo receipt only.</p><div class="checklist"><label><input type="checkbox" required>All agreed units received</label><label><input type="checkbox" required>Product details and condition checked</label></div><div class="form-actions"><button class="btn" type="submit">Confirm demo receipt</button></div></form>`,true);break;case'issue':showModal('Report a problem with the order',`<form id="issue-form" data-id="${id}"><label class="field">What needs review?<select name="type"><option>Missing units</option><option>Damaged goods</option><option>Wrong size, material or finish</option><option>Late delivery</option></select></label><label class="field" style="margin-top:15px">Details<textarea name="note" required minlength="10" maxlength="500" placeholder="Say how many products are affected and what was agreed."></textarea></label><p class="definition">This records a demo case for review. It does not promise refunds, insurance or unsold-stock buyback.</p><div class="form-actions"><button class="btn" type="submit">Record demo issue</button></div></form>`,true);break;case'orderdetail':orderDetail(id);break;case'downloadorder':{const o=state.orders.find(o=>o.id===id);download(o.id+'-DEMO.txt',`MEESHO MERCHANT — DEMO ORDER RECORD\nNOT A TAX INVOICE OR PAYMENT RECEIPT\n${o.id}\n${o.title}\nSupplier(s): ${o.supplier}\nQuantity: ${o.qty}\nProducts: ${money(o.goods)}\nDelivery: ${money(o.freight)}\nSample: ${money(o.sample||0)}\nBuying help fee: ${money(o.fee)}\nDemo payable: ${money(o.payable)}\nStatus: ${o.status}\nAll data illustrative.`);break;}case'reorder':{const o=state.orders.find(o=>o.id===id);state.cart=structuredClone(o.items);persist();navigate('cart');toast('Review current stock and terms before a repeat order.');break;}case'exportquotes':{const r=request(id);const csvrow=v=>'"'+String(v).replaceAll('"','""')+'"';download(r.id+'-DEMO-comparison.csv',[['DEMO DATA ONLY','Supplier','Products + setup','Delivery','Sample','Buying help fee','Cost of paying earlier (estimate)','Possible losses (estimate)','Estimated total cost','Payable'],...r.quotes.map(q=>{const c=quoteCost(r,q);return ['Illustrative',q.supplier,c.goods,q.freight,q.sample,c.fee,c.credit.toFixed(2),q.loss,c.total.toFixed(2),c.payable];})].map(row=>row.map(csvrow).join(',')).join('\n'),'text/csv');break;}case'about':showModal('A buying assistant for your shop',`<p>Merchant helps your shop buy the right products in quantities you can use. One buying job means confirming the list, comparing total cost, agreeing terms, tracking delivery and checking receipt. Choose help per job or through a monthly plan.</p><div class="receipt"><div><span>Basic discovery</span><strong>Free</strong></div><div><span>One buying job</span><strong>₹349 proposed</strong></div><div><span>Up to 4 jobs/month</span><strong>₹1,199 proposed</strong></div><div><span>Supplier sales commission</span><strong>0%</strong></div></div><p>This is a demo with example records. It does not provide loans, hold payments or guarantee stock.</p>`,true);break;case'demohelp':showModal('Ready for a presentation',`<p>Choose either role, replay the walkthrough, and switch sides to show the connected journey. This browser remembers demo activity.</p><div class="checklist"><div>Buyer → towel request → compare → approve sample → simulated order</div><div>Seller → orders → confirm stock → pack → dispatch</div><div>Buyer → orders → record receipt → repeat purchase</div><div>Buyer → new request → seller quote → buyer comparison</div></div><div class="actions">${role?button('Replay walkthrough','tour','','secondary full'):''}${button('Reset all demo activity','resetconfirm','','danger full')}</div><p class="definition">No external accounts, live messages, payments or shipping. Reset restores the 24 products and two example requests.</p>`,true);break;case'resetconfirm':showModal('Reset this demo?',`<p>This clears only the prototype’s local products, requests, quotes, plan selection and orders. Your project research files are unaffected.</p><div class="actions">${button('Keep my session','close','','secondary')}${button('Reset demo','reset','','danger')}</div>`,true);break;case'reset':state=seed();persist();role=null;view='home';tourStep=-1;filter='All products';query='';onlySaved=false;closeModal();render();toast('Demo reset. Choose a role to start again.');break;}});
document.addEventListener('input',event=>{if(event.target.matches('.quantity-slider')){setQuantity(event.target.closest('.quantity-pricing'),event.target.value);return;}if(event.target.id==='search'){query=event.target.value;const pos=event.target.selectionStart;render();const s=document.getElementById('search');s.focus();s.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{const el=event.target;if(el.name==='category'&&el.closest('#request-form')){const f=el.closest('form'),p=state.products.find(p=>p.category===el.value);f.elements.namedItem('spec').value=p?`${p.spec}, ${p.colour}. New unused stock. Confirm material, dimensions, finish and sample before bulk purchase.`:'';}if(el.id==='sort'){sort=el.value;render();}if(el.name==='service'){state.service=el.value;persist();render();}if(el.id==='baseline'){const n=Number(el.value);request().baseline=Number.isFinite(n)?Math.max(0,n):0;persist();render();}if(el.id==='credit-required'){request().payment=el.checked?'Need existing 30-day supplier credit':'Advance is workable';persist();render();}});
document.addEventListener('submit',event=>{const f=event.target;if(!f.id.endsWith('-form'))return;event.preventDefault();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(f.id==='request-form'){const first=state.products.find(p=>p.category===d.category);const id='REQ-'+(103+state.requests.filter(r=>r.id!=='REQ-101'&&r.id!=='REQ-102').length);state.requests.unshift({...d,id,qty:Number(d.qty),budget:Number(d.budget),baseline:Number(d.baseline)||0,productId:first?.id||0,status:'Awaiting quotes',sampleApproved:false,quotes:[],messages:[]});persist();selectedRequest=id;navigate('requests');toast('Demo request published. Switch to seller to prepare a quote.');}if(f.id==='quote-form'){const r=request(f.dataset.id);r.quotes.push({id:'Q-'+Date.now(),supplier:'Panipat Loomworks',type:'Manufacturer',price:Number(d.price),moq:Number(d.moq),stock:Number(d.stock),lead:Number(d.lead),freight:Number(d.freight),sample:Number(d.sample),setup:Number(d.setup),days:Number(d.days),loss:200,note:d.note,requiresSample:r.kind!=='Ready stock'||!!d.requiresSample,confirmed:false});r.status='Quotes ready';persist();closeModal();navigate('quotes');toast('Demo quote submitted. Switch to buyer to compare it.');}if(f.id==='sample-form'){const r=request(f.dataset.request);r.sampleApproved=true;r.approvedQuote=f.dataset.quote;persist();reviewQuote(r.id,f.dataset.quote);}if(f.id==='listing-form'){const n=Number(d.moq),stock=Number(d.stock),discounts=[0,Number(d.discount2),Number(d.discount4),Number(d.discount8)];if(discounts.some((v,i)=>!Number.isFinite(v)||v<0||v>30||(i&&v<discounts[i-1])))return toast('Discounts must increase or stay equal with quantity, between 0% and 30%.');if(n>stock)return toast('Minimum quantity must not exceed your available stock.');let p=f.dataset.id!==undefined?product(f.dataset.id):null;if(p)Object.assign(p,{name:d.name,category:d.category,price:Number(d.price),moq:n,stock,discounts,spec:d.spec,colour:d.colour});else{const id=Math.max(...state.products.map(p=>p.id))+1;state.products.push({id,name:d.name,category:d.category,price:Number(d.price),moq:n,stock,discounts,spec:d.spec,colour:d.colour,supplier:'Panipat Loomworks',type:'Manufacturer',active:true,photoId:Number(d.photo)});}persist();closeModal();navigate('inventory');toast('Stock saved. It is now available on the buyer side.');}if(f.id==='message-form'){if(/\b\S+@\S+\.\S+\b|(?:\+91[\s-]?)?\b\d{10}\b/.test(d.message))return toast('Leave out phone numbers and email addresses. Ask about the product, quantity or delivery instead.');const r=request(f.dataset.id);r.messages.push({by:role,text:d.message});persist();messagesModal(r.id);toast('Message saved in the shared demo request.');}if(f.id==='receive-form'){state.orders.find(o=>o.id===f.dataset.id).status='Received';persist();closeModal();render();toast('Demo receipt recorded. You can now build a repeat basket.');}if(f.id==='issue-form'){state.orders.find(o=>o.id===f.dataset.id).issue=d.type+': '+d.note;persist();closeModal();render();toast('Demo problem recorded for review.');}});
document.addEventListener('keydown',event=>{const overlay=document.getElementById('overlay');if(event.key==='Escape'){if(overlay.innerHTML)closeModal();else if(tourStep>=0){tourStep=-1;render();}}if(event.key==='Tab'&&overlay.innerHTML){const focusables=[...overlay.querySelectorAll('button,input,select,textarea,a[href]')].filter(e=>!e.disabled);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.getElementById('overlay').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
render();
